 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Remove the 3 divider. Highlight the ends of the repeated diagonal pattern.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 3:
                g[r][c] = 0
    # In the demos, highlighted cells sit at the top/bottom ends of each pattern.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 2 and ((r % 5 == 0 and c % 5 in (1, 2)) or
                                 (r % 5 == 2 and c % 5 == 0)):
                g[r][c] = 8
    return g
